def get_icon_svg(name: str, color: str = "#0284c7", size: int = 18, centered: bool = False) -> str:
    """Return an inline SVG string for the specified icon name.
    
    Args:
        name: Icon name key from SVG_ICONS.
        color: Stroke color hex string.
        size: Width/height in pixels.
        centered: When True, removes margin-right so the icon centers properly
                  inside flex circle containers (role cards, feature icons, etc.).
    """
    template = SVG_ICONS.get(name, SVG_ICONS["info"])
    svg = template.format(color=color, size=size)
    if centered:
        svg = svg.replace(
            'style="vertical-align: middle; margin-right: 6px;"',
            'style="display: block; margin: 0 auto;"'
        )
    return svg
